import {uid,dateKey,addDays,monday,minutes,endTime,overlap,unavailableOn,slotsOn,conflicts,load,moveTask,snapshotDay,seed} from './model.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='rhythm.v1';let state;try{state=JSON.parse(localStorage.getItem(KEY))||seed();}catch{state=seed();}
let view='week',week=monday(dateKey()),day=dateKey(),wizard=null,selectedCategory=null,blockFilter='week';
const days=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'],fullDays=['Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'];
const cat=id=>state.categories.find(c=>c.id===id)||{name:'Без блока',color:'#888',tag:''};
const fmt=n=>`${Math.round(n/60*10)/10} ч`,dateFmt=k=>new Date(k+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short'});
const btn=(text,action,data='',cls='')=>`<button class="${cls}" data-action="${action}" ${data}>${text}</button>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Не удалось сохранить данные. Экспортируйте резервную копию.');}}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500);}
function modal(title,body){$('#modal').innerHTML=`<h2>${title}</h2>${body}`;if(!$('#modal').open)$('#modal').showModal();}
function close(){$('#modal').close();wizard=null;}
function actions(extra=''){return `<div class="actions">${btn('Отмена','close')}${extra}</div>`;}
function field(label,input){return `<label>${label}${input}</label>`;}
function input(name,type='text',value='',attrs=''){return `<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}>`;}
function select(name,options,value){return `<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select>`;}
function categorySelect(value){return select('category',state.categories.map(c=>[c.id,c.name]),value);}
function render(){const titles={week:'Неделя',day:'Мой день',results:'Итоги',settings:'Настройки',blocks:'Блоки'};
$('#app').innerHTML=`<div class="layout"><aside><div class="brand"><img src="logo.svg" alt="" width="45" height="40"><span>паровозики</span></div><div class="tagline">ВРЕМЯ ДЛЯ ВАЖНОГО</div><nav>${Object.entries(titles).map(([id,t])=>btn(t,'nav',`data-view="${id}"`,id===view?'active':'')).join('')}</nav><div class="aside-bottom">Планируйте с запасом.<br>Оставляйте место для жизни.<div class="local">● Данные в этом браузере<br><span class="small">Версия 0.1 · без синхронизации</span></div></div></aside><main class="main"><div class="train-banner"><img src="train.svg" alt="" aria-hidden="true"></div><div class="topbar"><span class="eyebrow">Личное пространство / ${titles[view]}</span><p>${new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})}</p></div>${({week:renderWeek,day:renderDay,results:renderResults,settings:renderSettings,blocks:renderBlocks})[view]() }<div class="footer">Паровозики · ваш план может меняться, история остаётся.</div></main></div>`;updateClock();}
function heading(title,sub,controls=''){return `<div class="heading"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${controls}</div></div>`;}
function stats(items){return `<div class="stats">${items.map(([label,val,note])=>`<div class="stat"><span class="muted">${label}</span><strong>${val}</strong><small>${note}</small></div>`).join('')}</div>`;}
function renderWeek(){const dates=Array.from({length:7},(_,i)=>addDays(week,i)),ss=state.slots.filter(s=>dates.includes(s.date)),ts=state.tasks.filter(t=>dates.includes(t.date));let overs=0;for(const d of dates)for(const c of state.categories)overs+=load(state,c.id,d).overflow;const issues=conflicts(state).filter(c=>ss.some(s=>s.id===c.slot));return heading('Неделя в вашем ритме','Распределите время между важными направлениями.',btn('Шаблон недели','template')+btn('+ Добавить задачу','task','','primary'))+stats([['Время в блоках',fmt(ss.reduce((n,s)=>n+s.duration,0)),'Распределено на эту неделю'],['Запланировано',fmt(ts.reduce((n,t)=>n+t.estimate,0)),`${ts.length} задач в плане`],['Перегрузка',fmt(overs),overs?'Есть задачи для корректировки':'Всё помещается в блоки']])+`<div class="week-tools"><div class="actions">${btn('←','week-prev','aria-label="Предыдущая неделя"')}<span class="week-label">${dateFmt(week)} — ${dateFmt(addDays(week,6))}</span>${btn('→','week-next','aria-label="Следующая неделя"')}</div><div class="actions">${btn('Текущая неделя','week-now')}${btn('Корректировка','adjust')}</div></div>`+(issues.length?`<div class="notice">${issues.map(i=>esc(i.text)).join('<br>')}</div>`:'')+`<div class="week">${dates.map((d,i)=>`<section class="day ${d===dateKey()?'today':''}"><div class="day-head"><span>${days[i]} ${d===dateKey()?'· сегодня':''}</span><b>${new Date(d+'T12:00:00').getDate()}</b></div>${state.unavailable.filter(e=>unavailableOn(e,d)).map(e=>`<div class="block" style="--color:#a0a69b"><div class="time">${e.start}–${endTime(e.start,e.duration)}</div><div class="block-title">◷ ${esc(e.title)}</div><div class="capacity">Недоступное время</div></div>`).join('')}${slotsOn(state,d).sort((a,b)=>a.start.localeCompare(b.start)).map(s=>slotCard(s)).join('')}${state.tasks.filter(t=>t.date===d&&!slotsOn(state,d).some(s=>s.category===t.category)).map(t=>`<div class="block" style="--color:${cat(t.category).color}"><div class="pill warn">Нет интервала</div><div class="task-mini">${esc(t.title)}<span>${esc(cat(t.category).name)} · ${t.estimate} мин</span></div>${btn('Перенести','move',`data-id="${t.id}"`)}</div>`).join('')}${btn('+ Интервал','slot',`data-date="${d}"`,'add-slot')}</section>`).join('')}</div><div class="note"><span style="font-size:26px">◌</span><p><strong>План — это договорённость с собой</strong>Если задача займёт больше времени, Ритм поможет пересмотреть остальные блоки дня.</p></div>`;}
function slotCard(s){const c=cat(s.category),l=load(state,c.id,s.date),first=slotsOn(state,s.date).filter(x=>x.category===c.id).sort((a,b)=>a.start.localeCompare(b.start))[0];const ts=first.id===s.id?state.tasks.filter(t=>t.date===s.date&&t.category===c.id):[];return `<div class="block" style="--color:${c.color}"><div class="time">${s.start}–${endTime(s.start,s.duration)}</div>${btn(esc(c.name),'open-block',`data-id="${c.id}"`,'block-title block-link')}<div class="capacity ${l.overflow?'warn':''}">${l.planned} / ${l.budget} мин за день</div><div class="bar"><span style="--color:${l.overflow?'#c77c58':c.color};width:${l.budget?l.planned/l.budget*100:0}%"></span></div>${ts.map(t=>`<div class="task-mini ${t.done?'done':''}">${esc(t.title)}<span>${t.estimate} мин ${t.done?'· готово':''}</span></div>`).join('')}${btn('Изменить','slot',`data-id="${s.id}" data-date="${s.date}"`,'small soft')}</div>`;}
function dateControl(){return `<input id="selected-day" type="date" value="${day}" aria-label="Выбрать день" style="width:auto">`;}
function renderDay(){const ts=state.tasks.filter(t=>t.date===day),ss=slotsOn(state,day).sort((a,b)=>a.start.localeCompare(b.start)),started=!!state.baselines[day];return heading('Один день. Один фокус.','Начните с одной задачи, остальное уже в плане.',dateControl()+btn('+ Задача','task','','primary'))+`<div class="cols"><div>${!started?`<div class="panel"><h2>Готовы начать день?</h2><p class="muted">Зафиксируем исходный план, чтобы вечером сравнить его с результатом.</p>${btn('Запустить день','start-day','','primary')}</div>`:`<p class="pill">Исходный план сохранён · ${state.baselines[day].tasks.length} задач</p>`}${ss.length?ss.map(s=>{const c=cat(s.category),l=load(state,c.id,day);return `<div class="panel" style="border-top:3px solid ${c.color}"><div class="actions" style="justify-content:space-between"><h2>${btn(esc(c.name),'open-block',`data-id="${c.id}"`,'block-link')}</h2><span class="muted">${s.start}–${endTime(s.start,s.duration)}</span></div><p class="small ${l.overflow?'warn':'muted'}">План ${l.planned} мин · факт ${Math.round(l.actual)} мин · доступно ${l.budget} мин</p>${ss.filter(x=>x.category===s.category)[0].id===s.id?ts.filter(t=>t.category===s.category).map(taskRow).join('')||'<div class="empty">Здесь пока нет задач</div>':'<p class="muted small">Задачи показаны в первом интервале этого блока.</p>'}</div>`;}).join(''):'<div class="panel empty">На этот день ещё нет интервалов.<br>Добавьте их в плане недели.</div>'}${ts.filter(t=>!ss.some(s=>s.category===t.category)).length?`<div class="panel"><h2>Без интервала</h2>${ts.filter(t=>!ss.some(s=>s.category===t.category)).map(taskRow).join('')}</div>`:''}</div><div>${timerPanel()}<div class="panel"><h2>Оставить место для жизни</h2><p class="muted">Незапланированное дело тоже занимает время. Добавьте его, чтобы увидеть реальную нагрузку.</p>${btn('+ Записать дело','task')}<hr style="border:0;border-top:1px solid #e5e8df;margin:22px 0"><p class="small muted">Помодоро: 25 минут фокуса, затем предложение сделать перерыв. Таймер считает время по часам, в том числе при свёрнутой вкладке.</p></div></div></div>`;}
function taskRow(t){return `<div class="task"><span class="dot" style="--color:${cat(t.category).color}"></span><div class="body ${t.done?'done':''}">${esc(t.title)}<small>${t.estimate} мин план · ${Math.round(t.actual)} мин факт</small></div><div class="actions">${!t.done?btn('▶','focus',`data-id="${t.id}" aria-label="Начать ${esc(t.title)}"`,'soft')+btn('✓','complete',`data-id="${t.id}" aria-label="Завершить задачу"`):''}${btn('↗','move',`data-id="${t.id}" aria-label="Перенести задачу"`)}</div></div>`;}
function timerPanel(){const timer=state.timer,t=timer&&state.tasks.find(x=>x.id===timer.task);return `<div class="panel timer"><div class="eyebrow">Время фокуса</div><h2 style="margin-top:20px">${t?esc(t.title):'Выберите задачу'}</h2><div class="clock" id="clock">25:00</div><p class="muted small" id="timer-status">${timer?'Фокус-сессия':'Нажмите ▶ рядом с задачей'}</p><div class="actions">${timer?btn(timer.running?'Пауза':'Продолжить','timer-toggle','','primary')+btn('Завершить сессию','timer-stop'):''}</div></div>`;}
function renderBlocks(){
 const c=cat(selectedCategory||state.categories[0]?.id);selectedCategory=state.categories.find(x=>x.id===selectedCategory)?.id||state.categories[0]?.id;
 const today=dateKey(),start=week,end=addDays(start,6);
 const tasks=state.tasks.filter(t=>t.category===selectedCategory&&(blockFilter==='all'||(blockFilter==='today'?t.date===today:t.date>=start&&t.date<=end))).sort((a,b)=>a.date.localeCompare(b.date)||Number(a.done)-Number(b.done)||a.title.localeCompare(b.title,'ru'));
 const dates=[...new Set(tasks.map(t=>t.date))];const done=tasks.filter(t=>t.done).length;
 const period=blockFilter==='today'?'Сегодня, '+dateFmt(today):blockFilter==='week'?'Неделя: '+dateFmt(start)+' — '+dateFmt(end):'За всё время';
 return heading('Дела блока', 'Все задачи направления в одном месте.',btn('+ Добавить задачу','task','','primary'))+`<div class="actions block-tabs" aria-label="Выбор блока">${state.categories.map(x=>btn(`<span class="dot" style="--color:${x.color}"></span> ${esc(x.name)}`,'block-select',`data-id="${x.id}" aria-pressed="${x.id===selectedCategory}"`,x.id===selectedCategory?'primary':'')).join('')}</div><section class="panel"><div class="heading"><div><h2>${esc(cat(selectedCategory).name)}</h2><p class="subtitle">${period}</p></div><div class="actions" aria-label="Период задач">${[['today','Сегодня'],['week','Неделя'],['all','Все']].map(([key,label])=>btn(label,'block-filter',`data-filter="${key}" aria-pressed="${key===blockFilter}"`,key===blockFilter?'primary':'')).join('')}</div></div>${stats([['Задач',tasks.length,`${tasks.length-done} осталось · ${done} завершено`],['План',fmt(tasks.reduce((n,t)=>n+t.estimate,0)),'Оценка выбранных задач'],['Факт',fmt(tasks.reduce((n,t)=>n+t.actual,0)),'По этим задачам за всё время']])}${dates.map(d=>`<section class="block-date"><h3>${new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}${d===today?' · сегодня':''}</h3>${tasks.filter(t=>t.date===d).map(t=>`<div class="block-task">${taskRow(t)}<span class="pill ${!t.done&&!slotsOn(state,t.date).some(s=>s.category===t.category)?'warn':''}">${t.done?'Завершено':!slotsOn(state,t.date).some(s=>s.category===t.category)?'Нет интервала':'В плане'}</span></div>`).join('')}</section>`).join('')||`<div class="empty">${blockFilter==='all'?'В этом блоке пока нет задач.':'За выбранный период задач нет.'}<br>Добавьте задачу или выберите другой период.</div>`}</section>`;
}
function renderResults(){const baseline=state.baselines[day],original=baseline?.tasks||state.tasks.filter(t=>t.date===day);const planned=original.reduce((n,t)=>n+t.estimate,0),actual=state.sessions.filter(s=>s.date===day).reduce((n,s)=>n+s.minutes,0),moves=state.moves.filter(m=>m.from===day);const review=state.reviews[day]||{};return heading('Время без самообмана','Посмотрите на результат и отметьте, как вы себя чувствуете.',dateControl())+(!baseline?'<div class="notice">День ещё не запускался. Показан текущий план; исходный план не зафиксирован.</div>':'')+stats([['План на старте',fmt(planned),`${original.length} задач`],['Фактически',fmt(actual),'По завершённым фокус-сессиям'],['Перенесено',fmt(moves.reduce((n,m)=>n+m.minutes,0)),`${moves.length} переносов`]])+`<form id="review-form"><div class="review">${state.categories.map(c=>{const orig=original.filter(t=>t.category===c.id),done=orig.filter(t=>state.tasks.find(x=>x.id===t.id)?.done).length;const fact=state.sessions.filter(s=>s.date===day&&s.category===c.id).reduce((n,s)=>n+s.minutes,0);return `<div class="panel" style="border-top:3px solid ${c.color}"><h2>${esc(c.name)}</h2><p class="muted">${done} из ${orig.length} задач завершено · ${Math.round(fact)} мин фактически</p>${field('Насколько вы довольны результатом?',select(`rating-${c.id}`,[['','Без оценки'],['1','1 — совсем не довольна'],['2','2 — скорее не довольна'],['3','3 — нормально'],['4','4 — довольна'],['5','5 — очень довольна']],review.ratings?.[c.id]||''))}</div>`;}).join('')}</div><div class="panel"><h2>Что повлияло на день?</h2><p class="muted">${Math.abs(planned-actual)>=60?'План и факт заметно различаются. Можно записать причину.':'Комментарий поможет лучше спланировать следующую неделю.'}</p>${field('Причина',select('reason',[['','Не выбрана'],['hidden','Скрытые или незапланированные дела'],['complex','Задачи оказались сложнее'],['interruptions','Отвлечения'],['priorities','Изменились приоритеты'],['other','Другое']],review.reason||''))}${field('Комментарий',`<textarea name="comment" placeholder="Что стоит учесть в следующий раз?">${esc(review.comment||'')}</textarea>`)}<button class="primary">Сохранить итоги</button></div></form>`;}
function renderSettings(){return heading('Настроить под себя','Ваши направления, ограничения и привычный ритм недели.')+`<div class="settings-grid"><section class="panel"><div class="heading"><h2>Ваши блоки</h2>${btn('+ Блок','category','','soft')}</div>${state.categories.map(c=>`<div class="row"><div><span class="dot" style="--color:${c.color}"></span> ${esc(c.name)}<small>#${esc(c.tag)}</small></div>${btn('Изменить','category',`data-id="${c.id}"`,'small')}</div>`).join('')}</section><section class="panel"><div class="heading"><h2>Недоступное время</h2>${btn('+ Событие','unavailable','','soft')}</div><p class="muted small">Созвоны, курс и другие фиксированные события. Приложение проверяет пересечения с интервалами.</p>${state.unavailable.map(e=>`<div class="row"><div>${esc(e.title)}<small>${e.repeat==='weekly'?fullDays[e.weekday]+' · еженедельно':dateFmt(e.from)} · ${e.start}–${endTime(e.start,e.duration)}${e.until?' · до '+dateFmt(e.until):''}</small></div>${btn('×','delete-event',`data-id="${e.id}" aria-label="Удалить событие"`)}</div>`).join('')||'<p class="muted">Событий пока нет.</p>'}</section><section class="panel"><h2>Telegram</h2><span class="pill">Подключение — следующий этап</span><p class="muted">Личный чат с ботом: задача → блок → длительность → дата → подтверждение.</p><p class="small muted">Сейчас можно проверить этот сценарий прямо в приложении. Это локальная форма, сообщения в Telegram не отправляются.</p>${btn('Попробовать добавление','task','','primary')}<p class="small muted">Для настоящего бота понадобятся сервер, привязка аккаунта и секретный токен.</p></section><section class="panel"><h2>Данные и шаблон</h2><p class="muted">Данные сохраняются только в этом браузере. Для переноса на другое устройство используйте экспорт и импорт.</p><div class="actions">${btn('Экспорт JSON','export')}${btn('Импорт JSON','import')}</div><input type="file" id="import-file" accept="application/json" hidden><div class="row"><span class="muted small">Часовой пояс устройства</span><span class="small">${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}</span></div><div class="row"><span>Повторяемая неделя</span>${btn('Настроить','template')}</div></section></div>`;}
function showTask(){wizard={step:0,title:'',category:view==='blocks'?(selectedCategory||state.categories[0]?.id):state.categories[0]?.id,estimate:30,date:view==='blocks'?dateKey():day};showWizard();}
function showWizard(){const w=wizard;let body=`<div class="steps">${[0,1,2,3,4].map(i=>`<span class="${i<=w.step?'on':''}"></span>`).join('')}</div>`;const titles=['Что нужно сделать?','В какой блок?','Сколько времени планируем?','На какой день?','Всё верно?'];if(w.step===0)body+=`<form id="wizard-title">${field('Название задачи',input('title','text',w.title,'required maxlength="240" autofocus'))}<div class="actions">${btn('Отмена','close')}<button class="primary">Дальше →</button></div></form>`;if(w.step===1)body+=`<div class="choices">${state.categories.map(c=>btn(`<span class="dot" style="--color:${c.color}"></span> ${esc(c.name)}`,'wizard-cat',`data-id="${c.id}"`)).join('')}</div>`;if(w.step===2)body+=`<div class="choices">${[15,30,45,60,90,120].map(n=>btn(n+' мин','wizard-duration',`data-minutes="${n}"`)).join('')}</div><form id="wizard-custom" style="margin-top:18px">${field('Или своя длительность, минуты',input('estimate','number',w.estimate,'min="1" max="1440" required'))}<button>Дальше →</button></form>`;if(w.step===3)body+=`<div class="choices">${btn('Сегодня','wizard-date',`data-date="${dateKey()}"`)}${btn('Завтра','wizard-date',`data-date="${addDays(dateKey(),1)}"`)}</div><p class="muted small">Ближайшие семь дней</p><div class="choices">${Array.from({length:7},(_,i)=>{const d=addDays(dateKey(),i);return btn(`${fullDays[(new Date(d+'T12:00:00').getDay()+6)%7]}<br><small>${dateFmt(d)}</small>`,'wizard-date',`data-date="${d}"`);}).join('')}</div><form id="wizard-calendar" style="margin-top:18px">${field('Или конкретная дата',input('date','date',w.date,'required'))}<button>Выбрать дату →</button></form>`;if(w.step===4){const l=load(state,w.category,w.date);body+=`<div class="chat"><strong>${esc(w.title)}</strong><br>${esc(cat(w.category).name)} · ${w.estimate} мин<br>${dateFmt(w.date)}</div>`+(l.budget-l.actual-l.remaining<w.estimate?`<div class="notice">${!l.budget?'В этот день у блока нет интервала.':'Задача превышает свободное время блока на '+Math.ceil(w.estimate-(l.budget-l.actual-l.remaining))+' мин.'} Можно вернуться к выбору даты или сохранить для корректировки.</div>`:`<p class="muted">После добавления останется ${Math.floor(l.budget-l.actual-l.remaining-w.estimate)} мин.</p>`)+`<div class="actions">${btn('Изменить','wizard-reset')}${btn('Добавить задачу','wizard-save','','primary')}</div>`;}if(w.step>0)body+=`<div class="actions">${btn('Отмена','close')}${btn('← Назад','wizard-back')}</div>`;modal(titles[w.step],body);}
function showSlot(id,date){const s=state.slots.find(x=>x.id===id);modal(s?'Изменить интервал':'Новый интервал',`<form id="slot-form" data-id="${id||''}">${field('Блок',categorySelect(s?.category))}${field('Дата',input('date','date',date,'required'))}${field('Начало',input('start','time',s?.start||'09:00','required'))}${field('Продолжительность, минуты',input('duration','number',s?.duration||120,'required min="15" max="1440" step="15"'))}${actions((s?btn('Удалить','delete-slot',`data-id="${s.id}"`,'danger'):'')+'<button class="primary">Сохранить</button>')}</form>`);}
function showCategory(id){const c=state.categories.find(x=>x.id===id);modal(c?'Настройки блока':'Новый блок',`<form id="category-form" data-id="${id||''}">${field('Название',input('name','text',c?.name||'','required maxlength="60"'))}${field('Telegram-тег',input('tag','text',c?.tag||'','required pattern="[A-Za-zА-Яа-яЁё0-9_]+"'))}${field('Цвет',input('color','color',c?.color||'#7c9a7d'))}${actions('<button class="primary">Сохранить</button>')}</form>`);}
function showUnavailable(){modal('Недоступное время',`<form id="event-form">${field('Название',input('title','text','','required maxlength="100"'))}${field('Повторение',select('repeat',[['once','Один раз'],['weekly','Еженедельно']],'once'))}${field('День недели (для повторения)',select('weekday',fullDays.map((s,i)=>[String(i),s]),'0'))}${field('Дата / начало периода',input('from','date',day,'required'))}${field('Конец периода (необязательно)',input('until','date',''))}${field('Начало',input('start','time','18:00','required'))}${field('Продолжительность, минуты',input('duration','number',60,'required min="1" max="1440"'))}${actions('<button class="primary">Сохранить</button>')}</form>`);}
function showTemplate(){modal('Шаблон недели',`<p class="muted">Сохраните интервалы открытой недели как шаблон. При применении задачи и существующие интервалы сохраняются; точные дубликаты не добавляются.</p><p>Открытая неделя: <strong>${dateFmt(week)} — ${dateFmt(addDays(week,6))}</strong></p><p class="muted">В шаблоне ${state.template.length} интервалов.</p><div class="actions">${btn('Отмена','close')}${btn('Сохранить эту неделю','template-save')}${btn('Применить к этой неделе','template-apply','','primary')}</div>`);}
function showMove(id){const t=state.tasks.find(t=>t.id===id);modal('Перенести задачу',`<p>${esc(t.title)}</p><form id="move-form" data-id="${id}">${field('Новая дата',input('date','date',addDays(t.date,1),'required'))}<p class="muted small">После переноса задача появится в своём блоке. Если места нет, она останется видна в корректировке.</p>${actions('<button class="primary">Перенести</button>')}</form>`);}
function showAdjust(){const dates=Array.from({length:7},(_,i)=>addDays(week,i));const problems=[];for(const d of dates)for(const c of state.categories){const l=load(state,c.id,d);if(l.overflow>0)problems.push(`<div class="panel"><h3>${esc(c.name)} · ${dateFmt(d)}</h3><p class="warn">Не помещается ${Math.ceil(l.overflow)} мин</p>${state.tasks.filter(t=>t.date===d&&t.category===c.id&&!t.done).map(t=>`<div class="row"><span>${esc(t.title)} · ${Math.ceil(Math.max(0,t.estimate-t.actual))} мин осталось</span>${btn('Перенести','move',`data-id="${t.id}"`)}</div>`).join('')}${slotsOn(state,d).filter(s=>s.category===c.id).map(s=>btn('Изменить интервал','slot',`data-id="${s.id}" data-date="${d}"`)).join('')}</div>`);}const collisions=conflicts(state).filter(x=>state.slots.some(s=>s.id===x.slot&&dates.includes(s.date)));modal('Корректировка недели',(collisions.length?`<div class="notice">${collisions.map(x=>esc(x.text)).join('<br>')}</div>`:'')+(problems.join('')||'<p class="muted">Перегрузки задач нет. Все дела помещаются в свои блоки.</p>')+`<div class="actions">${btn('Закрыть','close')}</div>`);}
function accrued(timer){return timer.elapsed+(timer.running?(Date.now()-timer.started)/1000:0);}
function updateClock(){const t=state.timer;if($('#clock')){const seconds=t?Math.max(0,Math.ceil(1500-accrued(t))):1500;$('#clock').textContent=`${Math.floor(seconds/60).toString().padStart(2,'0')}:${(seconds%60).toString().padStart(2,'0')}`;if(t&&$('#timer-status'))$('#timer-status').textContent=t.running?'Фокус-сессия идёт':'Пауза';}}
function startFocus(id){if(state.timer){toast('Сначала завершите текущую сессию.');return;}const t=state.tasks.find(x=>x.id===id),slot=slotsOn(state,t.date).filter(s=>s.category===t.category);if(!slot.length){toast('Добавьте интервал для блока этой задачи.');return;}if(t.date!==dateKey()){toast('Таймер доступен для задач сегодняшнего дня.');return;}if(!state.baselines[t.date]&&(conflicts(state).some(x=>slotsOn(state,t.date).some(s=>s.id===x.slot))||state.categories.some(c=>load(state,c.id,t.date).overflow>0))){toast('Сначала скорректируйте план дня: есть перегрузка или пересечения.');return;}snapshotDay(state,t.date);state.timer={task:id,date:t.date,category:t.category,elapsed:0,started:Date.now(),running:true,estimateWarned:false,blockWarned:false};save();view='day';day=t.date;render();}
function stopSession(message=true){const timer=state.timer;if(!timer)return;const elapsed=accrued(timer)/60,t=state.tasks.find(x=>x.id===timer.task);if(elapsed>0){t.actual+=elapsed;state.sessions.push({id:uid(),task:t.id,category:t.category,date:timer.date,minutes:elapsed,at:Date.now()});}state.timer=null;save();render();if(message)modal('Сессия завершена',`<p>${esc(t.title)} · ${Math.round(elapsed)} мин фокуса.</p><p class="muted">Можно сделать перерыв или продолжить работу новой сессией.</p><div class="actions">${btn('Закрыть','close')}${btn('Задача готова','complete',`data-id="${t.id}"`,'primary')}</div>`);}
function pauseTimer(){const t=state.timer;if(t?.running){t.elapsed=accrued(t);t.running=false;save();}updateClock();}
function inspectTimer(){const timer=state.timer;if(!timer?.running)return;const task=state.tasks.find(t=>t.id===timer.task),extra=accrued(timer)/60,l=load(state,task.category,timer.date),now=new Date(),nowMin=now.getHours()*60+now.getMinutes(),ss=slotsOn(state,timer.date).filter(s=>s.category===task.category),lastEnd=Math.max(...ss.map(s=>minutes(s.start)+s.duration));const outside=timer.date!==dateKey()||!ss.some(s=>nowMin>=minutes(s.start)&&nowMin<minutes(s.start)+s.duration);
if(!timer.blockWarned&&(l.actual+extra>=l.budget||outside)){timer.blockWarned=true;pauseTimer();const affected=state.tasks.filter(t=>t.date===timer.date&&!t.done&&t.id!==task.id);modal('Время блока закончилось',`<div class="notice">Таймер приостановлен. Продолжение меняет план дня — сначала пересмотрите оставшиеся задачи.</div><p>Оставшиеся задачи всех блоков:</p>${affected.map(t=>`<div class="row"><span>${esc(cat(t.category).name)} · ${esc(t.title)}</span>${btn('Перенести','move',`data-id="${t.id}"`)}</div>`).join('')||'<p class="muted">Других незавершённых задач сегодня нет.</p>'}<p class="small muted">Для продолжения увеличьте интервал в неделе, устраните пересечения и перезапустите сессию.</p><div class="actions">${btn('Завершить сессию','timer-stop','','primary')}</div>`);return;}
if(!timer.estimateWarned&&task.actual+extra>=task.estimate){timer.estimateWarned=true;pauseTimer();modal('Оценённое время задачи истекло',`<p>${esc(task.title)}</p><p class="muted">Можно оставить остальные задачи в плане и продолжить до конца блока или перенести часть дел.</p>${state.tasks.filter(t=>t.date===timer.date&&t.category===task.category&&!t.done&&t.id!==task.id).map(t=>`<div class="row"><span>${esc(t.title)}</span>${btn('Перенести','move',`data-id="${t.id}"`)}</div>`).join('')}<div class="actions">${btn('Завершить сессию','timer-stop')}${btn('Оставить план и продолжить','timer-toggle','','primary')}</div>`);return;}
if(accrued(timer)>=1500){pauseTimer();stopSession();}}
$('#app').addEventListener('click',handle);$('#modal').addEventListener('click',handle);
function handle(e){const b=e.target.closest('[data-action]');if(!b)return;const {action:a,id,date}=b.dataset;
if(a==='open-block'){selectedCategory=id;blockFilter='week';view='blocks';render();return;}if(a==='block-filter'){blockFilter=b.dataset.filter;render();return;}if(a==='block-select'){selectedCategory=id;render();return;}if(a==='close')return close();if(a==='nav'){view=b.dataset.view;render();}if(a==='week-prev'){week=addDays(week,-7);render();}if(a==='week-next'){week=addDays(week,7);render();}if(a==='week-now'){week=monday(dateKey());render();}if(a==='task')showTask();if(a==='slot')showSlot(id,date);if(a==='category')showCategory(id);if(a==='unavailable')showUnavailable();if(a==='adjust')showAdjust();if(a==='move')showMove(id);if(a==='template')showTemplate();
if(a==='delete-slot'){state.slots=state.slots.filter(s=>s.id!==id);save();close();render();}if(a==='delete-event'){state.unavailable=state.unavailable.filter(s=>s.id!==id);save();render();}
if(a==='template-save'){state.template=state.slots.filter(s=>s.date>=week&&s.date<=addDays(week,6)).map(({category,start,duration,date})=>({category,start,duration,weekday:(new Date(date+'T12:00:00').getDay()+6)%7}));save();close();toast('Шаблон сохранён');}
if(a==='template-apply'){const proposed=state.template.map(t=>({...t,id:uid(),date:addDays(week,t.weekday)})).filter(t=>!state.slots.some(s=>s.date===t.date&&s.start===t.start&&s.category===t.category&&s.duration===t.duration));const merged={...state,slots:[...state.slots,...proposed]};if(conflicts(merged).length>conflicts(state).length){toast('Шаблон создаёт пересечения. Сначала измените интервалы или события.');return;}state.slots.push(...proposed);save();close();render();toast('Шаблон применён');}
if(a==='wizard-cat'){wizard.category=id;wizard.step=2;showWizard();}if(a==='wizard-duration'){wizard.estimate=+b.dataset.minutes;wizard.step=3;showWizard();}if(a==='wizard-date'){wizard.date=date;wizard.step=4;showWizard();}if(a==='wizard-back'){wizard.step--;showWizard();}if(a==='wizard-reset'){wizard.step=0;showWizard();}if(a==='wizard-save'){state.tasks.push({id:uid(),title:wizard.title,category:wizard.category,estimate:wizard.estimate,date:wizard.date,originalDate:wizard.date,actual:0,done:false,createdAt:Date.now()});save();close();render();toast('Задача добавлена');}
if(a==='start-day'){if(day!==dateKey()){toast('Запустить можно сегодняшний день.');return;}const issues=conflicts(state).filter(x=>slotsOn(state,day).some(s=>s.id===x.slot));const overloaded=state.categories.some(c=>load(state,c.id,day).overflow>0);if(issues.length||overloaded){toast('Сначала устраните пересечения и перегрузку в корректировке недели.');return;}snapshotDay(state,day);save();render();}
if(a==='focus')startFocus(id);if(a==='timer-stop'){close();stopSession();}if(a==='timer-toggle'){const t=state.timer;if(!t)return;if(t.blockWarned){toast('Время блока закончилось. Завершите сессию и скорректируйте интервалы.');return;}if(t.running)pauseTimer();else{t.running=true;t.started=Date.now();save();}if($('#modal').open)close();render();}
if(a==='complete'){const t=state.tasks.find(t=>t.id===id);if(state.timer?.task===id)stopSession(false);t.done=true;save();if($('#modal').open)close();render();}
if(a==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`rhythm-${dateKey()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}if(a==='import')$('#import-file').click();}
document.addEventListener('change',async e=>{if(e.target.id==='selected-day'){day=e.target.value||dateKey();render();}if(e.target.id==='import-file'){const f=e.target.files[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!validImport(data))throw Error('Неверный формат');modal('Импорт резервной копии',`<p>Заменить текущие данные? В копии ${data.tasks.length} задач. Сначала экспортируйте текущий план, если хотите сохранить его.</p>${actions(btn('Заменить данные','confirm-import','','primary'))}`);const b=$('[data-action="confirm-import"]');b.onclick=()=>{state=data;state.timer=null;save();close();render();toast('Данные восстановлены');};}catch{toast('Не удалось импортировать файл: неверный формат данных.');}}});
function validImport(d){
 const id=v=>typeof v==='string'&&/^[a-z0-9_-]+$/i.test(v),text=v=>typeof v==='string',date=v=>text(v)&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(new Date(v+'T12:00:00').getTime()),time=v=>text(v)&&/^([01]\d|2[0-3]):[0-5]\d$/.test(v),num=v=>Number.isFinite(v)&&v>=0,duration=v=>num(v)&&v>0&&v<=1440;
 if(d?.version!==1||!['categories','slots','tasks','template','unavailable','moves','sessions'].every(k=>Array.isArray(d[k]))||!d.baselines||Array.isArray(d.baselines)||!d.reviews||Array.isArray(d.reviews))return false;
 const ref=v=>d.categories.some(c=>c.id===v),interval=s=>ref(s.category)&&time(s.start)&&duration(s.duration)&&minutes(s.start)+s.duration<=1440;
 return d.categories.length>0&&new Set(d.categories.map(c=>c.id)).size===d.categories.length&&d.categories.every(c=>id(c.id)&&text(c.name)&&text(c.tag)&&/^#[0-9a-f]{6}$/i.test(c.color))&&d.slots.every(s=>id(s.id)&&date(s.date)&&interval(s))&&d.template.every(s=>interval(s)&&Number.isInteger(s.weekday)&&s.weekday>=0&&s.weekday<=6)&&d.tasks.every(t=>id(t.id)&&text(t.title)&&date(t.date)&&duration(t.estimate)&&num(t.actual)&&typeof t.done==='boolean'&&ref(t.category))&&d.unavailable.every(s=>id(s.id)&&text(s.title)&&date(s.from)&&(!s.until||date(s.until))&&['once','weekly'].includes(s.repeat)&&Number.isInteger(s.weekday)&&s.weekday>=0&&s.weekday<=6&&time(s.start)&&duration(s.duration))&&d.moves.every(m=>id(m.id)&&id(m.task)&&text(m.title)&&date(m.from)&&date(m.to)&&num(m.minutes))&&d.sessions.every(s=>id(s.id)&&id(s.task)&&ref(s.category)&&date(s.date)&&num(s.minutes))&&Object.entries(d.baselines).every(([k,b])=>date(k)&&Array.isArray(b.tasks)&&b.tasks.every(t=>id(t.id)&&ref(t.category)&&text(t.title)&&duration(t.estimate)))&&Object.entries(d.reviews).every(([k,r])=>date(k)&&r&&typeof r==='object'&&r.ratings&&typeof r.ratings==='object'&&text(r.reason)&&text(r.comment));
}
document.addEventListener('submit',e=>{const f=e.target;if(!f.id)return;e.preventDefault();const d=Object.fromEntries(new FormData(f));
if(f.id==='wizard-title'){if(!d.title.trim())return;wizard.title=d.title.trim();wizard.step=1;showWizard();}
if(f.id==='wizard-custom'){wizard.estimate=+d.estimate;wizard.step=3;showWizard();}if(f.id==='wizard-calendar'){wizard.date=d.date;wizard.step=4;showWizard();}
if(f.id==='slot-form'){const duration=+d.duration;if(minutes(d.start)+duration>1440){toast('Интервал должен заканчиваться в этот же день.');return;}const slot={id:f.dataset.id||uid(),category:d.category,date:d.date,start:d.start,duration};const others=state.slots.filter(s=>s.id!==slot.id&&s.date===slot.date);if(others.some(s=>overlap(s,slot))||state.unavailable.some(s=>unavailableOn(s,slot.date)&&overlap(s,slot))){toast('Есть пересечение с другим интервалом или недоступным временем.');return;}state.slots=state.slots.filter(s=>s.id!==slot.id);state.slots.push(slot);save();close();render();}
if(f.id==='category-form'){if(!d.name.trim())return;if(state.categories.some(c=>c.id!==f.dataset.id&&c.tag.toLowerCase()===d.tag.toLowerCase())){toast('Этот тег уже используется другим блоком.');return;}const c={id:f.dataset.id||uid(),name:d.name.trim(),tag:d.tag,color:d.color};state.categories=state.categories.filter(x=>x.id!==c.id);state.categories.push(c);save();close();render();}
if(f.id==='event-form'){if(d.until&&d.until<d.from){toast('Конец периода раньше начала.');return;}if(minutes(d.start)+Number(d.duration)>1440){toast('Событие должно заканчиваться в тот же день.');return;}state.unavailable.push({id:uid(),...d,weekday:+d.weekday,duration:+d.duration});save();close();render();toast('Событие добавлено. Пересечения отмечены в неделе.');}
if(f.id==='move-form'){moveTask(state,f.dataset.id,d.date);save();close();render();toast('Задача перенесена. Проверьте нагрузку нового дня.');}
if(f.id==='review-form'){state.reviews[day]={ratings:Object.fromEntries(state.categories.map(c=>[c.id,d['rating-'+c.id]])),reason:d.reason,comment:d.comment};save();toast('Итоги сохранены');}});
window.addEventListener('storage',e=>{if(e.key===KEY){toast('План изменён в другой вкладке. Перезагрузите эту вкладку перед продолжением.');}});
setInterval(()=>{updateClock();inspectTimer();},1000);render();
